#!/usr/bin/env Rscript
if (!requireNamespace("ape", quietly=TRUE) || !requireNamespace("pkgload", quietly=TRUE) || !requireNamespace("statmod", quietly=TRUE)) stop("needs ape/pkgload/statmod")
out <- "docs/dev-log/evidence/ou-v1-r31"; dir.create(out, recursive=TRUE, showWarnings=FALSE); pkgload::load_all(".", compile=TRUE, quiet=TRUE)
set.seed(2026091401); tree<-ape::rcoal(3); tree$tip.label<-paste0("sp",1:3); tree$edge.length<-tree$edge.length/max(ape::node.depth.edgelength(tree)[1:3]); d<-ape::cophenetic.phylo(tree); u<-drop(t(chol(.45^2*exp(-.7*d)))%*%rnorm(3)); v<-drop(t(chol(.25^2*exp(-1.3*d)))%*%rnorm(3)); species<-rep(tree$tip.label,each=3); ii<-match(species,tree$tip.label); dat<-data.frame(y=u[ii]+rnorm(9,sd=exp(-1+v[ii])),species=species)
fit_point <- function(a, s) { f<-bf(y~phylo(1|species,tree=tree,model="ou"),sigma~phylo(1|species,tree=tree,model="ou")); c<-drmTMB:::drm_parse_control(drm_control()); z<-drmTMB:::drm_build_gaussian_ls_spec(f,dat,env=environment(),weights=NULL,control=c,impute=NULL,missing=drmTMB:::drm_parse_missing_control(miss_control())); z$map$log_decay_phylo<-factor(c(NA,NA));z$start$log_decay_phylo<-log(a);z$map$log_sd_phylo<-factor(c(NA,NA));z$start$log_sd_phylo<-log(s); drmTMB:::drm_fit_spec(z,f,gaussian(),c,REML=FALSE,penalty=NULL,estimator="ml") }
quad <- function(mu,ls,s,a,n) { q<-statmod::gauss.quad.prob(n,"normal"); g<-as.matrix(expand.grid(rep(list(q$nodes),6))); lw<-rowSums(log(as.matrix(expand.grid(rep(list(q$weights),6))))); L1<-t(chol(s[[1]]^2*exp(-a[[1]]*d)));L2<-t(chol(s[[2]]^2*exp(-a[[2]]*d)));x<-g[,1:3]%*%L1;z<-g[,4:6]%*%L2; for(j in seq_len(nrow(dat))) lw<-lw+dnorm(dat$y[j],mu+x[,ii[j]],exp(ls+z[,ii[j]]),log=TRUE); m<-max(lw); -(m+log(sum(exp(lw-m)))) }
points<-list(interior=list(a=c(.7,1.3),s=c(.45,.25)),ridge=list(a=c(8,8),s=c(.19,.057))); ans<-do.call(rbind,lapply(names(points),function(id){p<-points[[id]];fit<-suppressWarnings(fit_point(p$a,p$s));mu<-unname(fit$par$mu[[1]]);ls<-unname(fit$par$sigma[[1]]);q5<-quad(mu,ls,p$s,p$a,5);q7<-quad(mu,ls,p$s,p$a,7);data.frame(point=id,alpha_mu=p$a[1],alpha_sigma=p$a[2],sd_mu=p$s[1],sd_sigma=p$s[2],mu=mu,logsigma=ls,laplace=fit$opt$objective,quadrature5=q5,quadrature7=q7,laplace_minus_q7=fit$opt$objective-q7,refinement=abs(q7-q5))}))
utils::write.csv(ans,file.path(out,"comparison.csv"),row.names=FALSE);ape::write.tree(tree,file.path(out,"tree.nwk"));utils::write.csv(dat,file.path(out,"data.csv"),row.names=FALSE);writeLines(c("# R3.1 exact marginal diagnostic","","Small-tree only; not a G15 or recovery claim."),file.path(out,"RESULTS.md"));cat("OU_V1_R31_RUN_PASS\n")
